INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 25, 'theory', 'Quiz: cache');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 25, 0, 'How does cache-aside work for reads and writes?', '["Read: the cache, on a miss the database and a write to the cache; write: change the database and delete or update the cache entry", "The application writes only to the cache, and the database updates itself", "The cache itself reads the database on every request and writes to it", "Both stores are updated by independent processes without the application"]', 0, 'The cache does not have to be reliable: a lost cache is just a cold start. The drawback is that caching logic lives in the application, and a forgotten invalidation yields stale data.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 25, 1, 'What is a cache stampede and how do you fight it?', '["Cache memory overflow; you need more memory", "A network failure; you need replicas", "A simultaneous miss on a popular entry, when thousands of requests hit the database; cured by a single recompute, early refresh and TTL jitter", "A clock failure; you need NTP"]', 2, 'The first request takes a lock and recomputes the value, and the others wait or get a slightly stale one; random spread in expiry stops entries from expiring in a bunch.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 25, 2, 'What trouble can happen if the cache key for personal data has no user identifier?', '["The cache will not be able to evict entries", "One user will see an answer meant for another: a data leak", "The cache will become slower", "TTL will stop working"]', 1, 'The key must be a function of all request parameters: language, currency, permissions and user. Otherwise the cache mixes up responses.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 25, 3, 'What do negative caching and a Bloom filter give you?', '["They speed up writes", "They reduce value size", "They encrypt keys", "They protect the database from requests for nonexistent keys, which always miss the cache"]', 3, 'We remember "no such key" for a short time; for huge key spaces a Bloom filter quickly answers "definitely not" and keeps the request away from the database.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 25, 4, 'The cache hit ratio is 90%. What does that mean for the database load?', '["It did not change", "It dropped about tenfold: only misses reach the database", "It grew", "It dropped by 90 times"]', 1, '10% of requests go to the database. That is why the hit ratio is the main cache metric; a low hit ratio means the cache only adds latency and complexity.');
